// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 bn, uint256 ts, address actor) public {
        bn = bound(bn, 15, type(uint256).max - 1);
        ts = bound(ts, 2, type(uint256).max - 2);
        vm.roll(bn);
        vm.warp(ts);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        // General rule: at any block number divisible by 15, after a successful
        // 10-ether fallback call the contract has transferred out its entire balance.
        assertTrue(bn % 15 != 0 || address(c).balance == 0);
    }
}
